    public static boolean canSplit(int[] arr) {
        int total = 0;
        for (int x : arr) total += x;

        if (total % 2 != 0) return false;

        int half = total / 2;
        int leftSum = 0;

        for (int x : arr) {
            leftSum += x;
            if (leftSum == half) return true;
        }
        return false;
    }

    public static void main(String[] args) {
        System.out.println(canSplit(new int[]{1,2,3,4,5,5}));
        System.out.println(canSplit(new int[]{1,2,3}));
